'use client';
import { useState, useEffect } from 'react';
import { Stethoscope, Plus, Tag, Search, Filter, Building2 } from 'lucide-react';

export default function ServiceManagement() {
  const [services, setServices] = useState([]);
  const [hospitals, setHospitals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    hospital_id: '',
    name: '',
    category: 'Lab', // Default
    price: '',
    discount_price: '',
    description: ''
  });

  useEffect(() => {
    fetchServices();
    fetchHospitals();
  }, []);

  const fetchServices = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/services');
      if (res.ok) {
        const data = await res.json();
        setServices(data);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchHospitals = async () => {
      try {
        const res = await fetch('http://localhost:5000/api/hospitals');
        if (res.ok) {
          const data = await res.json();
          setHospitals(data);
        }
      } catch (err) {
        console.error(err);
      }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
        const res = await fetch('http://localhost:5000/api/services', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(formData)
        });

        if (res.ok) {
            alert('Service Added Successfully!');
            setShowForm(false);
            setFormData({ hospital_id: '', name: '', category: 'Lab', price: '', discount_price: '', description: '' });
            fetchServices(); 
        } else {
            alert('Failed to add service');
        }
    } catch (err) {
        console.error(err);
    }
  };

  if (showForm) {
      return (
          <div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
                  <h1>Add New Service</h1>
                  <button className="btn btn-outline" onClick={() => setShowForm(false)}>Cancel</button>
              </div>
              
              <div className="glass" style={{ padding: '2rem', maxWidth: '600px' }}>
                  <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                      
                      <div>
                          <label style={{ display: 'block', marginBottom: '0.5rem', color: 'var(--text-muted)' }}>Service Name</label>
                          <input 
                            type="text" required placeholder="e.g. MRI Scan, CBC Test"
                            value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})}
                            style={{ width: '100%', padding: '0.8rem', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', borderRadius: '8px' }}
                          />
                      </div>

                      <div style={{ display: 'flex', gap: '1rem' }}>
                          <div style={{ flex: 1 }}>
                              <label style={{ display: 'block', marginBottom: '0.5rem', color: 'var(--text-muted)' }}>Category</label>
                              <select 
                                value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}
                                style={{ width: '100%', padding: '0.8rem', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', borderRadius: '8px' }}
                              >
                                  <option value="Lab" style={{ color: '#000' }}>Lab Test</option>
                                  <option value="Scan" style={{ color: '#000' }}>Scan / X-Ray</option>
                                  <option value="OPD" style={{ color: '#000' }}>OPD Consultation</option>
                                  <option value="Surgery" style={{ color: '#000' }}>Surgery</option>
                              </select>
                          </div>
                          <div style={{ flex: 1 }}>
                              <label style={{ display: 'block', marginBottom: '0.5rem', color: 'var(--text-muted)' }}>Assign To Hospital</label>
                              <select 
                                value={formData.hospital_id} onChange={e => setFormData({...formData, hospital_id: e.target.value})}
                                style={{ width: '100%', padding: '0.8rem', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', borderRadius: '8px' }}
                              >
                                  <option value="" style={{ color: '#000' }}>-- Global / Independent --</option>
                                  {hospitals.map(h => (
                                      <option key={h.id} value={h.id} style={{ color: '#000' }}>{h.name}</option>
                                  ))}
                              </select>
                          </div>
                      </div>

                      <div style={{ display: 'flex', gap: '1rem' }}>
                          <div style={{ flex: 1 }}>
                              <label style={{ display: 'block', marginBottom: '0.5rem', color: 'var(--text-muted)' }}>Original Price (₹)</label>
                              <input 
                                type="number" required
                                value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})}
                                style={{ width: '100%', padding: '0.8rem', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', borderRadius: '8px' }}
                              />
                          </div>
                          <div style={{ flex: 1 }}>
                              <label style={{ display: 'block', marginBottom: '0.5rem', color: 'var(--text-muted)' }}>Discounted Price (₹)</label>
                              <input 
                                type="number" required
                                value={formData.discount_price} onChange={e => setFormData({...formData, discount_price: e.target.value})}
                                style={{ width: '100%', padding: '0.8rem', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', borderRadius: '8px' }}
                              />
                          </div>
                      </div>

                      <div>
                          <label style={{ display: 'block', marginBottom: '0.5rem', color: 'var(--text-muted)' }}>Description (Optional)</label>
                          <textarea 
                            rows="3"
                            value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})}
                            style={{ width: '100%', padding: '0.8rem', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', borderRadius: '8px' }}
                          />
                      </div>

                      <button className="btn btn-primary" style={{ marginTop: '1rem' }}>Add Service</button>

                  </form>
              </div>
          </div>
      );
  }

  return (
    <div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
            <h1>Service Management</h1>
            <button className="btn btn-primary" onClick={() => setShowForm(true)}>
                <Plus size={18} style={{ marginRight: '8px' }} /> Add Service
            </button>
        </div>

        {/* Filters */}
        <div className="glass" style={{ padding: '1rem', display: 'flex', gap: '1rem', marginBottom: '2rem', alignItems: 'center' }}>
            <Search size={20} style={{ color: 'var(--text-muted)' }} />
            <input type="text" placeholder="Search services..." style={{ background: 'transparent', border: 'none', color: '#fff', flex: 1, outline: 'none' }} />
            <div style={{ width: '1px', height: '20px', background: 'rgba(255,255,255,0.1)' }}></div>
            <button style={{ background: 'transparent', border: 'none', color: 'var(--text-muted)', display: 'flex', gap: '5px' }}>
                <Filter size={18} /> Filter
            </button>
        </div>

        {/* Table */}
        <div className="glass" style={{ padding: '0', overflow: 'hidden' }}>
            <div style={{ overflowX: 'auto' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                    <thead>
                        <tr style={{ borderBottom: '1px solid rgba(255,255,255,0.1)', background: 'rgba(255,255,255,0.02)' }}>
                            <th style={{ padding: '1rem' }}>Service Name</th>
                            <th style={{ padding: '1rem' }}>Category</th>
                            <th style={{ padding: '1rem' }}>Hospital</th>
                            <th style={{ padding: '1rem' }}>Price</th>
                            <th style={{ padding: '1rem' }}>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {services.map((service) => (
                            <tr key={service.id} style={{ borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                                <td style={{ padding: '1rem' }}>
                                    <div style={{ fontWeight: '500' }}>{service.name}</div>
                                    <div style={{ fontSize: '0.85rem', color: 'var(--text-muted)' }}>{service.description}</div>
                                </td>
                                <td style={{ padding: '1rem' }}>
                                    <span style={{ 
                                        padding: '4px 10px', borderRadius: '20px', fontSize: '0.75rem',
                                        background: service.category === 'Lab' ? 'rgba(52, 152, 219, 0.2)' : 'rgba(155, 89, 182, 0.2)',
                                        color: service.category === 'Lab' ? '#3498db' : '#9b59b6'
                                    }}>
                                        {service.category}
                                    </span>
                                </td>
                                <td style={{ padding: '1rem' }}>
                                    {service.hospital_name ? (
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                                            <Building2 size={14} color="var(--text-muted)" /> {service.hospital_name}
                                        </div>
                                    ) : (
                                        <span style={{ color: 'var(--text-muted)', fontStyle: 'italic' }}>Platform Wide</span>
                                    )}
                                </td>
                                <td style={{ padding: '1rem' }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                                        <span style={{ textDecoration: 'line-through', color: 'var(--text-muted)', fontSize: '0.9rem' }}>₹{service.price}</span>
                                        <span style={{ color: 'var(--accent)', fontWeight: 'bold' }}>₹{service.discount_price}</span>
                                    </div>
                                </td>
                                <td style={{ padding: '1rem' }}>
                                    <button className="btn-link" style={{ color: '#ef4444' }}>Delete</button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                {services.length === 0 && !loading && (
                    <div style={{ padding: '3rem', textAlign: 'center', color: 'var(--text-muted)' }}>No services found. Add one to get started.</div>
                )}
            </div>
        </div>
    </div>
  );
}
